mapper.select:
SELECT q.id, q.query_id, q.ds_id, q.task_id, q.node_id, q.query_type, q.sql_text, q.sql_abstract, q.involved_tables, q.risk_level, q.verdict, q.review_status, q.executed, q.result_json, q.result_check_json, q.fix_suggestion, q.err_code, q.err_msg, q.cost_ms, q.create_time, q.update_time FROM rcagent_attribution_query_log q INNER JOIN rcagent_attribution_task t ON q.task_id = t.task_id WHERE q.is_deleted = 0 AND t.is_deleted = 0 AND q.review_status = 'NONE' AND t.status = 'QUERY_REVIEWING' AND t.review_state = 'QUERY_REVIEWING'
AND t.ds_id = #{dsId}
AND q.task_id = #{taskId}
ORDER BY q.create_time ASC, q.id ASC
